import secrets
import re

class AccountService:
    def __init__(self) -> None:
        self.accounts = {}  # email -> {'password': str, 'is_admin': bool}
        self.reset_tokens = {}  # token -> target_email

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long")

        if email in self.accounts:
            raise ValueError("Email already registered")

        # Store password as lowercase for case-insensitive comparison later
        self.accounts[email] = {
            'password': password.lower(),
            'is_admin': is_admin
        }

    def login(self, email: str, password: str) -> bool:
        if email not in self.accounts:
            return False

        # Compare case-insensitively
        return self.accounts[email]['password'] == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        # Check if requester is an admin
        if requester_email not in self.accounts or not self.accounts[requester_email]['is_admin']:
            raise PermissionError("Only administrators can request password resets")

        # Generate a secure random token
        token = secrets.token_urlsafe(32)

        # Store the token mapping to the target email
        self.reset_tokens[token] = target_email

        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long")

        if token not in self.reset_tokens:
            raise ValueError("Invalid or expired reset token")

        target_email = self.reset_tokens[token]

        # Remove the token so it can only be used once
        del self.reset_tokens[token]

        # Check if target email exists
        if target_email not in self.accounts:
            raise ValueError("Target email does not exist")

        # Update the password
        self.accounts[target_email]['password'] = new_password.lower()
